import logging
from typing import Optional
logger = logging.getLogger(__name__)

def parse_int(text: str, *, default: Optional[int] = None, strict: bool = True) -> Optional[int]:
    if text is None:
        if strict: raise TypeError('text required')
        return default
    if not isinstance(text, str):
        if strict: raise TypeError('text must be str')
        return default
    try:
        return int(text)
    except ValueError:
        if strict: raise
        logger.warning('parse failed; returning default')
        return default

