from dataclasses import dataclass

@dataclass
class Rectangle:
    width: float
    height: float

    @property
    def area(self) -> float:
        return self.width * self.height

def area(width: float, height: float) -> float:
    return Rectangle(width=width, height=height).area

def max3(a: int, b: int, c: int) -> int:
    # Step 1: compare a and b
    if a > b:
        # a is bigger than b
        if a > c:
            # a is bigger than c too
            return a  # return a as the max
        else:
            # c is bigger than a
            return c  # return c as the max
    else:
        # b is bigger than or equal to a
        if b > c:
            # b is bigger than c
            return b  # return b as the max
        else:
            # c is bigger than b
            return c  # return c as the max

